let language='ar';
document.querySelectorAll('[data-i18n]').forEach(el=>el.dataset.ar=el.innerHTML);
const langButton=document.getElementById('langBtn');
langButton.onclick=()=>{language=language==='ar'?'en':'ar';document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';langButton.textContent=language==='ar'?'EN':'ع';document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=language==='en'?(translations[el.dataset.i18n]||el.innerHTML):el.dataset.ar)};

const header=document.querySelector('.site-header');addEventListener('scroll',()=>header.classList.toggle('scrolled',scrollY>35),{passive:true});
const modal=document.getElementById('authModal'),toast=document.getElementById('toast');
function setTab(name){document.querySelectorAll('.auth-tabs button').forEach(button=>button.classList.toggle('active',button.dataset.tab===name));document.querySelectorAll('.auth-form').forEach(form=>form.classList.toggle('active',form.id===name+'Form'))}
function openAuth(name='register',plan){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setTab(name);const option=document.querySelector(`[name="plan"][value="${plan}"]`);if(option)option.checked=true;setTimeout(()=>modal.querySelector('.auth-form.active input')?.focus(),100)}
function closeAuth(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function notify(message){toast.querySelector('span').textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),4200)}
document.querySelectorAll('.open-register').forEach(button=>button.onclick=()=>openAuth('register',button.dataset.plan));
document.querySelectorAll('.open-login').forEach(button=>button.onclick=()=>openAuth('login'));
document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeAuth);
document.querySelectorAll('.auth-tabs button').forEach(button=>button.onclick=()=>setTab(button.dataset.tab));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeAuth()});
const registerForm=document.getElementById('registerForm'),loginForm=document.getElementById('loginForm');
function busy(form,state){const button=form.querySelector('[type=submit]');button.disabled=state;button.style.opacity=state?'.55':'1'}
registerForm.onsubmit=async event=>{event.preventDefault();busy(registerForm,true);const data=new FormData(registerForm);try{const result=await StrongGymAPI.signUp({email:data.get('email').trim(),password:data.get('password'),fullName:data.get('full_name').trim(),whatsapp:data.get('whatsapp').trim(),gender:data.get('gender'),plan:data.get('plan')});closeAuth();registerForm.reset();notify(result?.session?(language==='ar'?'تم إنشاء الحساب. يمكنك تسجيل الدخول الآن.':'Account created. You can sign in now.'):(language==='ar'?'تم إنشاء الحساب. افحص بريدك لتأكيده، ثم سجّل الدخول.':'Account created. Check your email to confirm it, then sign in.'))}catch(error){notify(error.message)}finally{busy(registerForm,false)}};
loginForm.onsubmit=async event=>{event.preventDefault();busy(loginForm,true);const data=new FormData(loginForm);try{await StrongGymAPI.signIn(data.get('email').trim(),data.get('password'));const profile=await StrongGymAPI.profile();if(!profile)throw new Error(language==='ar'?'لم يكتمل إنشاء الملف الشخصي. حاول مجدداً.':'Profile setup is incomplete. Try again.');if(profile.status==='blocked'||profile.status==='rejected')throw new Error(language==='ar'?'الحساب غير متاح. تواصل مع الإدارة.':'This account is unavailable. Contact management.');if(profile.status==='pending'){closeAuth();notify(language==='ar'?'حسابك بانتظار موافقة الإدارة وتأكيد الدفع.':'Your account is waiting for management approval and payment confirmation.');return}location.href=profile.role==='manager'||profile.role==='coach'?'admin.html':'member.html'}catch(error){notify(error.message)}finally{busy(loginForm,false)}};
document.querySelector('.forgot').onclick=async()=>{const email=loginForm.elements.email.value.trim();if(!email){notify(language==='ar'?'أدخل البريد الإلكتروني أولاً.':'Enter your email first.');return}try{await StrongGymAPI.recover(email);notify(language==='ar'?'أرسلنا رابط الاسترجاع إلى بريدك.':'Recovery link sent to your email.')}catch(error){notify(error.message)}};

const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(24px)'},{opacity:1,transform:'none'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll('.statement,.experience-head>*,.classes-head>*,.class-card,.plans-grid article,.time-cards article,.system-copy li,.contact-grid article').forEach(el=>{el.style.opacity='0';observer.observe(el)});
